import { useState, useEffect } from 'react';

function useDonnees(initialData = [], fetchFunction = null) {
// Au lieu d'utiliser useDonnees, vous pourriez essayer:
const [chambres, setChambres] = useState([]);
const [loading, setLoading] = useState(true);
const [error, setError] = useState(null);

useEffect(() => {
  const fetchData = async () => {
    try {
      setLoading(true);
      const data = await chambreService.getAll();
      setChambres(data);
      setError(null);
    } catch (err) {
      setError('Erreur lors du chargement des données');
      console.error('Erreur:', err);
    } finally {
      setLoading(false);
    }
  };

  fetchData();
}, []);


  const ajouterElement = async (element, createFunction = null) => {
    try {
      if (createFunction) {
        const resultat = await createFunction(element);
        
        // Si le résultat contient seulement un ID
        if (resultat && (resultat.id || resultat.insertId)) {
          // Créer un nouvel objet complet
          const nouveauElement = { 
            ...element, 
            id_chambre: resultat.id || resultat.insertId 
          };
          // Mettre à jour l'état avec le nouvel élément
          setDonnees(prevDonnees => [...prevDonnees, nouveauElement]);
          return nouveauElement;
        } else {
          // Si le résultat est l'objet complet
          setDonnees(prevDonnees => [...prevDonnees, resultat]);
          return resultat;
        }
      } else {
        setDonnees(prevDonnees => [...prevDonnees, element]);
        return element;
      }
    } catch (err) {
      setError("Erreur lors de l'ajout");
      throw err;
    }
  };

  const modifierElement = async (id, idField, nouvellesDonnees, updateFunction = null) => {
    try {
      if (updateFunction) {
        await updateFunction(id, nouvellesDonnees);
        // Mettre à jour l'état local
        setDonnees(prevDonnees => 
          prevDonnees.map(item => 
            item[idField] === id ? { ...item, ...nouvellesDonnees } : item
          )
        );
        return nouvellesDonnees;
      } else {
        setDonnees(prevDonnees => 
          prevDonnees.map(item => 
            item[idField] === id ? { ...item, ...nouvellesDonnees } : item
          )
        );
        return nouvellesDonnees;
      }
    } catch (err) {
      setError("Erreur lors de la modification");
      throw err;
    }
  };

  const supprimerElement = async (id, idField, deleteFunction = null) => {
    try {
      if (deleteFunction) {
        await deleteFunction(id);
        setDonnees(prevDonnees => prevDonnees.filter(item => item[idField] !== id));
      } else {
        setDonnees(prevDonnees => prevDonnees.filter(item => item[idField] !== id));
      }
    } catch (err) {
      setError("Erreur lors de la suppression");
      throw err;
    }
  };

  // SUPPRIMEZ CETTE PARTIE - C'est la cause de l'erreur
  // const { 
  //   donnees: chambres, 
  //   setDonnees: setChambres,
  //   loading, 
  //   error, 
  //   setError,
  //   ajouterElement,
  //   modifierElement,
  //   supprimerElement
  // } = useDonnees([], fetchChambres);

  return {
    donnees,
    setDonnees,
    loading,
    error,
    setError,
    ajouterElement,
    modifierElement,
    supprimerElement
  };
}

export default useDonnees;
